$(document).ready(function(){setInterval(function(){$('.time-ago').each(function(){$(this).html(cm_time_ago($(this).attr('data-time'))).attr('title',$(this).attr('data-time')).attr('data-bs-toggle','tooltip')});cm_tooltip()},1000)});function cm_ajax(url,type,data,begin,done,error,loading){cm_ajax_timeout(url,type,data,begin,done,error,loading,10000)}
function cm_ajax_timeout(url,type,data,begin,done,error,loading,timeout,cache){data.ajax=1;if(!cache){cache=!1}
if(url.substr(0,4)!='http'){url=cm_url_domain+url}
var request=$.ajax({url:url,method:'POST',cache:cache,data:data,dataType:type,timeout:timeout,beforeSend:function(){if(loading!=''){$('#'+loading).show()}
begin()}}).done(function(json){if(loading!=''){$('#'+loading).hide()}
done(json)}).fail(function(a,b,c){if(loading!=''){$('#'+loading).hide()}
error(a,b,c)})}
function cm_filesize(bytes){var type='bytes';if(bytes>512){bytes=bytes/1024;type='kB';if(bytes>512){bytes=bytes/1024;type='MB';if(bytes>512){bytes=bytes/1024;type='GB';if(bytes>512){bytes=bytes/1024;type='TB';if(bytes>512){bytes=bytes/1024;type='PB'}}}}}
return cm_number(bytes)+' '+type}
function cm_random_string(length){var result='';var characters='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';var characters_length=characters.length;for(var i=0;i<length;i++){result+=characters.charAt(Math.floor(Math.random()*characters_length))}
return result}
function cm_check_all(target,check){$(target).each(function(){if($(this).is(':visible')){$(this).prop('checked',check)}})}
function cm_time_ago(date){var units={year:24*60*60*1000*365,month:24*60*60*1000*365/12,day:24*60*60*1000,hour:60*60*1000,minute:60*1000,second:1000};var rtf=(Intl&&Intl.RelativeTimeFormat&&new Intl.RelativeTimeFormat('en',{numeric:'auto'}))||!1;if(!rtf){}else{var now=new Date();var elapsed=(parseInt(date)*1000)-now;for(var u in units){if((Math.abs(elapsed)>units[u])||(u=='second')){var output=rtf.format(Math.round(elapsed/units[u]),u);if(output=='now'){output='Just now'}else if(output=='yesterday'){output='Yesterday'}else if(output.substr(0,4)=='last'){output='Last'+output.substr(4)}
return output}}}}
function cm_time_date(date){var formatter=new DateFormatter();var formatted=formatter.parseDate((parseInt(date)*1000),'u');if(formatter.formatDate(formatted,'H:i:s')=='00:00:00'){formatted=formatter.formatDate(formatted,cm_data.ld)}else{formatted=formatter.formatDate(formatted,cm_data.lt)}
return formatted}
function cm_vehicle_spin(id){if(typeof cm_vehicle_spin_data.media[id]!='undefined'){for(var i=0;i<Object.keys(cm_vehicle_spin_data.media[id]).length;i++){if(cm_vehicle_spin_data.media[id][i]!=''){var img=document.createElement('img');img.src=cm_vehicle_spin_data.media[id][i];img.setAttribute('style','display:none;');img.setAttribute('id','cm_vehicle_spin_'+id+'_image_'+i);document.getElementById('cm_vehicle_spin_'+id+'_container').appendChild(img)}}
cm_vehicle_spin_data.load[id]=setInterval(function(){cm_vehicle_spin_loaded(id)},250);if(($('#cm_vehicle_spin_'+id+'_image').width()>0)&&($('#cm_vehicle_spin_'+id+'_image').height()>0)){var ratio=$('#cm_vehicle_spin_'+id+'_image').width()+'/'+$('#cm_vehicle_spin_'+id+'_image').height();$('#cm_vehicle_spin_'+id+', #cm_vehicle_spin_'+id+'_container').css({'aspect-ratio':ratio})}
$('#cm_vehicle_spin_'+id+' .psv-fullscreen-button').on('click',function(){cm_vehicle_spin_fullscreen(id)})}}
function cm_vehicle_spin_status(event,phase,direction,distance){distance=Math.floor(distance/10);var id=event.target.id.replace('cm_vehicle_spin_','').replace('_image','');if(typeof cm_vehicle_spin_data.timeout[id]=='undefined'){cm_vehicle_spin_data.timeout[id]=!1}else if(cm_vehicle_spin_data.timeout[id]!==!1){clearTimeout(cm_vehicle_spin_data.timeout[id])}
if(direction===null){if(typeof cm_vehicle_spin_data.direction[id]!='undefined'){direction=cm_vehicle_spin_data.direction[id]}}
if(direction=='right'){cm_vehicle_spin_data.direction[id]='right';cm_vehicle_spin_data.timeout[id]=setTimeout(function(){cm_vehicle_spin_img(id,'left',distance,phase)},1)}else if(direction=='left'){cm_vehicle_spin_data.direction[id]='left';cm_vehicle_spin_data.timeout[id]=setTimeout(function(){cm_vehicle_spin_img(id,'right',-distance,phase)},1)}}
function cm_vehicle_spin_img(id,direction,distance,phase){var total=Object.keys(cm_vehicle_spin_data.media[id]).length;var position=0;if(typeof cm_vehicle_spin_data.position[id]!='undefined'){position=cm_vehicle_spin_data.position[id]}
distance=distance+position;if((phase=='end')||(phase=='cancel')){cm_vehicle_spin_data.position[id]=distance}
if(direction=='left'){if(distance<1){distance+=total}
if(distance>total){distance-=total}}else{var total2=-Math.abs(total);if(distance>total2){distance+=total}
if(distance<=total2){distance+=total*2}}
while(distance>total){distance=distance-total}
while(distance<0){distance=distance+total}
if($('#cm_vehicle_spin_'+id+'_image_'+distance).length==0){distance=0}
$('#cm_vehicle_spin_'+id+'_container > img:not(#cm_vehicle_spin_'+id+'_image)').hide();$('#cm_vehicle_spin_'+id+'_image').show().css({'position':'absolute','opacity':0});$('#cm_vehicle_spin_'+id+'_image_'+distance).show()}
function cm_vehicle_spin_click(event,target,a,b){var id=event.target.id.replace('cm_vehicle_spin_','').replace('_image','');var x=event.x;var y=event.y;if(typeof event.x=='undefined'){x=event.pageX;y=event.pageY}
if(typeof cm_vehicle_spin_data.click[id]=='undefined'){cm_vehicle_spin_data.click[id]=!0}else if(cm_vehicle_spin_data.click[id]===!0){cm_vehicle_spin_data.click[id]=!1}else{cm_vehicle_spin_data.click[id]=!0}
var zoom=3;var fraction=(zoom*0.66666);if(cm_vehicle_spin_data.click[id]===!0){$('#'+event.target.id).css('transform','scale('+zoom+')');var size=[$('#'+event.target.id).width(),$('#'+event.target.id).height()];var offset=[x-10,y-10];var bottom=(offset[1]*fraction)-size[1];var bottom_abs=Math.abs(bottom);if(bottom>size[1]){bottom=size[1]}else if(bottom_abs<size[1]){bottom_abs=size[1]}
if(offset[1]>(size[1]/fraction)){bottom_abs=bottom}
var right=(offset[0]*fraction)-size[0];var right_abs=Math.abs(right);if(right>size[0]){right=size[0]}else if(right_abs<size[0]){right_abs=size[0]}
if(offset[0]>(size[0]/fraction)){right_abs=right}
$('#'+event.target.id).css('position','relative').css('right',right+'px').css('bottom',bottom+'px')}else{$('#'+event.target.id).css('transform','scale(1)');$('#'+event.target.id).css('position','relative').css('right','0px').css('bottom','0px')}}
function cm_vehicle_spin_fullscreen(id){var id=document.getElementById('cm_vehicle_spin_'+id);if(id.requestFullscreen){id.requestFullscreen()}else if(id.webkitRequestFullscreen){id.webkitRequestFullscreen()}else if(id.msRequestFullscreen){id.msRequestFullscreen()}}
function cm_vehicle_spin_loaded(id){var total=Object.keys(cm_vehicle_spin_data.media[id]).length;var complete=0;for(var i=0;i<total;i++){var img=document.getElementById('cm_vehicle_spin_'+id+'_image_'+i);if(!img.complete){}else if(img.naturalWidth===0){}else{complete++}}
var progress=(100/total)*complete;$('#cm_vehicle_spin_'+id+'_loading .progress').attr('aria-valuenow',progress);$('#cm_vehicle_spin_'+id+'_loading .progress-bar').css('width',progress+'%');if(progress>95){clearInterval(cm_vehicle_spin_data.load[id]);var options={triggerOnTouchEnd:!0,swipeStatus:cm_vehicle_spin_status,threshold:50};$('#cm_vehicle_spin_'+id).swipe(options);if(($('#cm_vehicle_spin_'+id+'_image').width()>0)&&($('#cm_vehicle_spin_'+id+'_image').height()>0)){var ratio=$('#cm_vehicle_spin_'+id+'_image').width()+'/'+$('#cm_vehicle_spin_'+id+'_image').height();$('#cm_vehicle_spin_'+id+', #cm_vehicle_spin_'+id+'_container').css({'aspect-ratio':ratio})}
$('#cm_vehicle_spin_'+id+'_loading').removeClass('d-flex').hide();$('#cm_vehicle_spin_'+id+' .helper').show()}}